644	func (t *timerQueueStandbyTaskExecutor) processTimer(
645		ctx context.Context,
646		timerTask tasks.Task,
647		actionFn standbyActionFn,
648		postActionFn standbyPostActionFn,
649	) (retError error) {
650		ctx, cancel := context.WithTimeout(ctx, taskTimeout)
651		defer cancel()
652	
653		nsRecord, err := t.shardContext.GetNamespaceRegistry().GetNamespaceByID(namespace.ID(timerTask.GetNamespaceID()))
654		if err != nil {
655			return err
656		}
657		if !nsRecord.IsOnCluster(t.clusterName) {
658			// namespace is not replicated to local cluster, ignore corresponding tasks
659			return nil
660		}
661	
662		executionContext, release, err := getWorkflowExecutionContextForTask(ctx, t.shardContext, t.cache, timerTask)
663		if err != nil {
664			return err
665		}
666		defer func() {
667			if errors.Is(retError, consts.ErrTaskRetry) {
668				release(nil)
669			} else {
670				release(retError)
671			}
672		}()
673	
674		mutableState, err := loadMutableStateForTimerTask(ctx, t.shardContext, executionContext, timerTask, t.metricsHandler, t.logger)
675		if err != nil {
676			return err
677		}
678		if mutableState == nil {
679			return nil
680		}
681	
682		historyResendInfo, err := actionFn(ctx, executionContext, mutableState, release)
683		if err != nil {
684			return err
685		}
686	
687		// NOTE: do not access anything related mutable state after this lock release
688		// Release is idempotent, so safe to call even if action already released
689		release(nil)
690		return postActionFn(ctx, timerTask, historyResendInfo, t.logger)
691	}
