694		ctx context.Context,
695		task tasks.Task,
696		postActionInfo any,
697		logger log.Logger,
698	) error {
699		if postActionInfo == nil {
700			return nil
701		}
702	
703		pushActivityInfo := postActionInfo.(*activityTaskPostActionInfo)
704		activityScheduleToStartTimeout := pushActivityInfo.activityTaskScheduleToStartTimeout
705		activityTask := task.(*tasks.ActivityRetryTimerTask)
706	
707		resp, err := t.matchingRawClient.AddActivityTask(ctx, &matchingservice.AddActivityTaskRequest{
708			NamespaceId: activityTask.NamespaceID,
709			Execution: &commonpb.WorkflowExecution{
710				WorkflowId: activityTask.WorkflowID,
711				RunId:      activityTask.RunID,
712			},
713			TaskQueue: &taskqueuepb.TaskQueue{
714				Name: pushActivityInfo.taskQueue,
715				Kind: enumspb.TASK_QUEUE_KIND_NORMAL,
716			},
717			ScheduledEventId:       activityTask.EventID,
718			ScheduleToStartTimeout: durationpb.New(activityScheduleToStartTimeout),
719			Clock:                  vclock.NewVectorClock(t.shardContext.GetClusterMetadata().GetClusterID(), t.shardContext.GetShardID(), activityTask.TaskID),
720			VersionDirective:       pushActivityInfo.versionDirective,
721			Stamp:                  activityTask.Stamp,
722		})
723	
724		if err != nil {
725			return err
726		}
727	
728		if pushActivityInfo.versionDirective.GetUseAssignmentRules() == nil {
729			// activity is not getting a new build ID, so no need to update MS
730			return nil
731		}
732	
733		return updateIndependentActivityBuildId(
734			ctx,
735			activityTask,
736			resp.AssignedBuildId,
737			t.shardContext,
738			historyi.TransactionPolicyPassive,
739			t.cache,
740			t.metricsHandler,
741			t.logger,
742		)
743	}

