		namespace.ID(task.GetNamespaceID()),
	)
	if err != nil {
		return respond(err)
	}

	if !nsRecord.IsOnCluster(e.clusterName) {
		// namespace is not replicated to local cluster, ignore corresponding tasks
		return respond(nil)
	}

	if err := validateTaskByClock(e.shardContext, task); err != nil {
		return respond(err)
